let avatarSerial=0;
function avatarSVG(settings={}) {
 const a={icon:'bolt',iconColor:'#fe7800',frame:'hex',frameColor:'#fe7800',background:'plain',halo:'spark',material:'solid',motion:'none',...settings};
 const prefix='av'+(++avatarSerial)+'-';
 const get=(category,id)=>{const body=AVATAR_ASSETS[category+'/'+id];if(body===undefined)throw Error('Unknown avatar item '+category+'/'+id);return body.replace(/id="([^"]+)"/g,(_,id)=>'id="'+prefix+category+'-'+id+'"').replace(/url\(#([^\)]+)\)/g,(_,id)=>'url(#'+prefix+category+'-'+id+')');};
 for(const value of [a.iconColor,a.frameColor])if(!/^#[0-9a-f]{6}$/i.test(value))throw Error('Invalid avatar color');
 if(!AVATAR_CONFIG.items.some(x=>x.category==='motion'&&x.id===a.motion))throw Error('Unknown motion');
 let frame=get('frames',a.frame);let material='';
 if(a.material!=='solid'){const swatch=get('materials',a.material);material=swatch.match(/<defs>[\s\S]*?<\/defs>/)[0];frame=frame.replace(/currentColor/g,'url(#'+prefix+'materials-material)');}
 const dots=a.motion==='orbit'?'<g class="orbit-points" fill="'+a.frameColor+'"><circle cx="50" cy="6" r="2"/><circle cx="88" cy="72" r="2"/><circle cx="12" cy="72" r="2"/></g>':'';
 const light=a.motion==='borderflow'?'<g class="frame-light" color="#ffffff">'+get('frames',a.frame)+'</g>':'';
 const rays=a.motion==='legend-aura'?'<g class="legend-rays" stroke="#ffe23f" opacity=".6"><circle cx="50" cy="50" r="46" stroke-dasharray="2 10" stroke-width="2"/><circle cx="50" cy="50" r="48" stroke-dasharray="1 14" stroke-width="1"/></g>':'';
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" class="avatar" data-motion="'+a.motion+'" fill="none" aria-hidden="true">'+material+'<g class="halo-layer" color="'+a.frameColor+'">'+get('halos',a.halo)+'</g><g color="'+a.iconColor+'">'+get('backgrounds',a.background)+'</g><g class="frame-layer" color="'+a.frameColor+'">'+frame+'</g>'+light+'<g class="icon-layer" color="'+a.iconColor+'">'+get('icons',a.icon)+'</g>'+dots+rays+'</svg>';
}
function unlockedItems(level,category){return AVATAR_CONFIG.items.filter(x=>x.category===category&&x.unlockLevel<=level);}
